To improve Numpy interoperability, torch tensors could implement the array interface in a quite simple manner:
def __array__(self, dtype=None):
    if dtype is None:
        return self.cpu().numpy()
    else:
        return self.cpu().numpy().astype(dtype, copy=False)


def __array_wrap__(self, array):
    if array.ndim == 0:
        if array.dtype.kind == 'b':
            return bool(array)
        elif array.dtype.kind in ('i', 'u'):
            return int(array)
        elif array.dtype.kind == 'f':
            return float(array)
        elif array.dtype.kind == 'c':
            return complex(array)
        else:
            raise RuntimeError
    else:
        if array.dtype == bool:
            # Workaround, torch has no built-in bool tensor
            cls = torch.ByteTensor
            array = array.astype('uint8')
        else:
            cls = _tensor_cls(array.dtype, use_cuda=self.is_cuda)
        return cls(array)


def _tensor_cls(dtype, use_cuda):
    mapping = {
        np.dtype('float16'): 'Half',
        np.dtype('float32'): 'Float',
        np.dtype('float64'): 'Double',
        np.dtype('int8'): 'Char',
        np.dtype('int16'): 'Short',
        np.dtype('int32'): 'Int',
        np.dtype('int64'): 'Long',
        np.dtype('uint8'): 'Byte',
    }
    try:
        name = mapping[np.dtype(dtype)]
    except KeyError:
        raise ValueError('dtype {} not supported'.format(dtype))
    if use_cuda:
        return getattr(torch.cuda, name)
    else:
        return getattr(torch, name)
It would enable simple things like numpy.asarray to turn tensors into Numpy arrays, and with that make basically all of Numpy applicable to torch tensors (with some restrictions). Is something like that of interest?

Hi, I wonder if there are plans to add support for assignment with Numpy arrays or sequence types.
A working but rather lame implementation for Numpy arrays would be
def __setitem__(self, indices, values):
    if isinstance(values, np.ndarray):
        values = torch.from_numpy(values)
    super(type(self), self).__setitem__(indices, values)
For list or sequences, one could do something equally lame:
def __setitem__(self, indices, values):
    if not isinstance(values, torch._TensorBase) and not np.isscalar(values):
        values = type(self)(values)
    super(type(self), self).__setitem__(indices, values)
This won't support broadcasting, but it may be better than nothing. A fix for broadcasting in whole-tensor assignment situations could be
def __setitem__(self, indices, values):
    ...
    def iterable(obj):
        try:
            iter(obj)
        except TypeError:
            return False
        else:
            return True

    if (isinstance(values, torch._TensorBase) and
            (indices in (slice(None), Ellipsis)) or
            (iterable(indices) and all(i in (slice(None), Ellipsis)
                                       for i in indices))):
        # Covers `x[:] = values`, `x[:, :] = values` etc, and `x[...] = values`
        self.copy_(values)

